// MOCK de clasificacion: esta PoC no tiene configurada una clave de API de
// Gemini ni de Groq (ver README.md / .env.example para las variables de
// entorno esperadas), por lo que se simula la clasificacion con reglas
// simples basadas en palabras clave del texto. Para produccion, sustituir
// este nodo por un nodo HTTP Request que llame al LLM elegido.

const body = $json.body || $json;
const description = body.description || '';
const latitude = body.latitude != null ? body.latitude : null;
const longitude = body.longitude != null ? body.longitude : null;

const text = description.toLowerCase();

const rules = [
  { keywords: ['fuga', 'agua', 'tuberia', 'tubería', 'inundacion', 'inundación'], incident_type: 'agua_saneamiento', severity: 'alta', priority: 5 },
  { keywords: ['incendio', 'fuego', 'humo'], incident_type: 'incendio', severity: 'alta', priority: 5 },
  { keywords: ['bache', 'hueco', 'pavimento', 'via', 'vía'], incident_type: 'infraestructura_vial', severity: 'media', priority: 3 },
  { keywords: ['basura', 'residuo', 'desecho'], incident_type: 'residuos', severity: 'baja', priority: 2 },
  { keywords: ['alumbrado', 'luz', 'poste', 'foco'], incident_type: 'alumbrado_publico', severity: 'media', priority: 3 },
  { keywords: ['arbol', 'árbol', 'rama'], incident_type: 'arbolado_urbano', severity: 'media', priority: 2 }
];

let match = rules.find(r => r.keywords.some(k => text.includes(k)));
if (!match) {
  match = { incident_type: 'otro', severity: 'baja', priority: 1 };
}

return [{
  json: {
    description,
    image_url: null,
    incident_type: match.incident_type,
    severity: match.severity,
    priority: match.priority,
    latitude,
    longitude
  }
}];

